<template>
  <div class="mx-auto max-w-6xl space-y-5 px-4 py-5 sm:px-6 lg:px-8">
    <header class="flex items-center gap-3"><Button icon="pi pi-chevron-left" rounded outlined severity="secondary" aria-label="Go back" title="Go back" size="small" @click="goBack" /><div><p class="text-xs font-semibold uppercase tracking-wide text-orange-700">Supplier product</p><h1 class="mt-1 text-xl font-semibold text-slate-900">{{ product?.product_name || 'Product Details' }}</h1><p class="mt-1 text-xs text-slate-500">Supplier SKU: {{ product?.supplier_sku || '—' }}</p></div></header>
    <div v-if="loading" class="space-y-3"><Skeleton height="9rem" /><Skeleton height="15rem" /></div>
    <template v-else-if="product">
      <Card class="border border-slate-200 shadow-none"><template #content><div class="grid gap-5 md:grid-cols-[minmax(0,1.5fr)_minmax(15rem,1fr)]"><div><div class="flex flex-wrap items-center gap-2"><h2 class="text-base font-semibold text-slate-900">{{ product.product_name }}</h2><Badge :value="product.is_active ? 'Active' : 'Inactive'" :severity="product.is_active ? 'success' : 'secondary'" /></div><p class="mt-1 text-sm text-slate-600">{{ product.description || 'No description provided.' }}</p><div class="mt-4 grid gap-3 sm:grid-cols-3"><div><p class="text-xs text-slate-500">Category</p><p class="mt-1 font-medium text-slate-900">{{ [product.category_name, product.subcategory_name].filter(Boolean).join(' · ') }}</p></div><div><p class="text-xs text-slate-500">Type</p><p class="mt-1 font-medium text-slate-900">{{ label(product.product_type) }}</p></div><div><p class="text-xs text-slate-500">Unit</p><p class="mt-1 font-medium text-slate-900">{{ product.unit_of_measurement }}</p></div></div></div><div v-if="product.images?.length" class="grid grid-cols-3 gap-2 sm:grid-cols-5 md:grid-cols-3"><img v-for="(image, index) in product.images" :key="index" :src="image.url" :alt="image.alt_text" class="h-24 w-full rounded-lg border border-slate-200 object-cover" /></div><div v-else class="flex min-h-24 items-center justify-center rounded-lg border border-dashed border-slate-300 text-xs text-slate-400">No product photos</div></div></template></Card>

      <Card class="border border-slate-200 shadow-none"><template #title><div><h2 class="text-base font-semibold text-slate-900">Product dimensions</h2><p class="mt-1 text-xs font-normal text-slate-500">Supplier catalog measurements in cm and kg.</p></div></template><template #content><div class="grid gap-3 sm:grid-cols-3 lg:grid-cols-5"><div v-for="item in dimensionRows(product.dimensions)" :key="item.label" class="rounded-lg bg-slate-50 p-3"><p class="text-xs text-slate-500">{{ item.label }}</p><p class="mt-1 font-medium text-slate-900">{{ item.value }}</p></div><div v-for="(item, index) in product.dimensions?.additional_measurements || []" :key="`custom-${index}`" class="rounded-lg bg-slate-50 p-3"><p class="text-xs text-slate-500">{{ item.label }}</p><p class="mt-1 font-medium text-slate-900">{{ item.value }} {{ item.unit }}</p></div></div></template></Card>

      <Card class="border border-slate-200 shadow-none"><template #title><div><h2 class="text-base font-semibold text-slate-900">Variants</h2><p class="mt-1 text-xs font-normal text-slate-500">Archive variants that are no longer offered. Archived variants are excluded from Procurement.</p></div></template><template #content><DataTable :value="product.variants || []" rowHover responsiveLayout="scroll" class="text-sm"><Column field="name" header="Variant" /><Column field="sku" header="Variant SKU" /><Column header="Attributes"><template #body="{ data }">{{ [data.color, data.size, data.material, data.texture, data.finish].filter(Boolean).join(' · ') || '—' }}</template></Column><Column header="Cost"><template #body="{ data }">{{ money(data.base_cost) }}</template></Column><Column header="Dimensions"><template #body="{ data }">{{ dimensionsText(data.dimensions) }}</template></Column><Column header="Photos"><template #body="{ data }"><div v-if="data.images?.length" class="flex gap-1"><img v-for="(image, index) in data.images.slice(0, 5)" :key="index" :src="image.url" :alt="image.alt_text" class="h-9 w-9 rounded border border-slate-200 object-cover" /></div><span v-else class="text-slate-400">—</span></template></Column><Column header="Status"><template #body="{ data }"><Badge :value="data.is_active ? 'Active' : 'Archived'" :severity="data.is_active ? 'success' : 'secondary'" /></template></Column><Column header="Actions"><template #body="{ data }"><Button v-if="data.is_active" label="Archive" icon="pi pi-box" severity="secondary" outlined size="small" :loading="archivingId === data.id" @click="archiveVariant(data)" /><span v-else class="text-xs text-slate-400">Unavailable</span></template></Column><template #empty><div class="py-6 text-center text-sm text-slate-500">No variants for this supplier product.</div></template></DataTable></template></Card>

      <Card class="border border-slate-200 shadow-none"><template #title><div><h2 class="text-base font-semibold text-slate-900">Store Offers</h2><p class="mt-1 text-xs font-normal text-slate-500">Each store offer has its own cost, tax, minimum order, lead time, availability, and active status.</p></div></template><template #content><DataTable :value="product.offers || []" rowHover responsiveLayout="scroll" class="text-sm"><Column field="store_name" header="Store" /><Column header="Base Cost"><template #body="{ data }">{{ money(data.base_cost) }}</template></Column><Column header="Tax"><template #body="{ data }">{{ data.is_tax_exempt ? 'Exempt' : `${number(data.tax_rate)}% · ${money(data.tax_amount)}` }}</template></Column><Column header="Cost Including Tax"><template #body="{ data }"><span class="font-semibold text-slate-900">{{ money(data.cost_including_tax) }}</span></template></Column><Column header="Order Terms"><template #body="{ data }">{{ data.minimum_order_quantity }} minimum · {{ data.lead_time_days }} day lead</template></Column><Column header="Availability"><template #body="{ data }"><Badge :value="availabilityLabel(data.availability_status)" :severity="availabilitySeverity(data.availability_status)" /></template></Column><Column header="Status"><template #body="{ data }"><Badge :value="data.is_active ? 'Active' : 'Inactive'" :severity="data.is_active ? 'success' : 'secondary'" /></template></Column></DataTable></template></Card>
    </template>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import Badge from 'primevue/badge'
import Button from 'primevue/button'
import Card from 'primevue/card'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import Skeleton from 'primevue/skeleton'
import { useToast } from 'primevue/usetoast'
import supplierService from '../../../services/supplier.service'
const route = useRoute(); const router = useRouter(); const toast = useToast(); const loading = ref(false); const archivingId = ref<number | null>(null); const product = ref<any>(null)
const load = async () => { loading.value = true; try { product.value = (await supplierService.getProductListing(String(route.params.id))).data } finally { loading.value = false } }
const archiveVariant = async (variant: any) => { if (!window.confirm(`Archive ${variant.name}? It will no longer be available to Procurement.`)) return; archivingId.value = Number(variant.id); try { await supplierService.archiveProductVariant(String(route.params.id), Number(variant.id)); await load(); toast.add({ severity: 'success', summary: 'Variant archived', detail: 'This variant is no longer available to Procurement.', life: 3000 }) } catch (error: any) { toast.add({ severity: 'error', summary: 'Unable to archive variant', detail: error?.response?.data?.message || 'The variant could not be archived.', life: 3500 }) } finally { archivingId.value = null } }
const goBack = () => window.history.length > 1 ? router.back() : router.push({ name: 'supplier.products' })
const money = (value: unknown) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(Number(value || 0))
const number = (value: unknown) => new Intl.NumberFormat('en-PH', { maximumFractionDigits: 2 }).format(Number(value || 0))
const label = (value: string) => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, letter => letter.toUpperCase())
const dimensionRows = (d: any) => [{ label: 'Length', value: d?.length_cm ? `${d.length_cm} cm` : '—' }, { label: 'Width', value: d?.width_cm ? `${d.width_cm} cm` : '—' }, { label: 'Height', value: d?.height_cm ? `${d.height_cm} cm` : '—' }, { label: 'Depth', value: d?.depth_cm ? `${d.depth_cm} cm` : '—' }, { label: 'Weight', value: d?.weight_kg ? `${d.weight_kg} kg` : '—' }]
const dimensionsText = (d: any) => [d?.length_cm && `L ${d.length_cm} cm`, d?.width_cm && `W ${d.width_cm} cm`, d?.height_cm && `H ${d.height_cm} cm`, d?.depth_cm && `D ${d.depth_cm} cm`, d?.weight_kg && `${d.weight_kg} kg`].filter(Boolean).join(' · ') || '—'
const availabilityLabel = (value: string) => ({ available: 'Available', limited: 'Limited', out_of_stock: 'Out of stock' } as Record<string, string>)[value] || 'Available'
const availabilitySeverity = (value: string) => ({ available: 'success', limited: 'warn', out_of_stock: 'danger' } as Record<string, string>)[value] || 'success'
onMounted(load)
</script>
